minimal_example.code:
-- B-tree (по умолчанию): равенство, диапазоны, сортировка
CREATE INDEX orders_created_idx ON orders (created_at);

-- GIN: поиск внутри JSONB
CREATE INDEX products_attrs_idx ON products USING gin (attrs);
SELECT * FROM products WHERE attrs @> '{"color": "red"}';

-- BRIN: огромная append-only таблица событий
CREATE INDEX events_ts_brin ON events USING brin (ts);

